def run(_context):
    import json
    import adsk.cam
    import adsk.core

    # Get the CAM product
    cam = mb.get_cam()

    # Find the Setup1 setup
    setup = None
    for s in cam.setups:
        if s.name == "Setup1":
            setup = s
            break

    if not setup:
        print("Setup1 not found!")
        return

    # Find the "Rough Profile" operation
    op = None
    for o in setup.operations:
        if o.name == "Rough Profile":
            op = o
            break

    if not op:
        print("Rough Profile not found!")
        return

    # Get the parameters
    params = op.parameters

    # Set integer parameters directly
    for param_name in ["maximumRoughingSteps", "numberOfFinishingStepovers"]:
        param = params.itemByName(param_name)
        if param:
            print(f"  {param_name}: type={type(param.value).__name__}, current={param.value.value}")
            if isinstance(param.value, adsk.cam.IntegerParameterValue):
                if param_name == "maximumRoughingSteps":
                    param.value.value = 2
                elif param_name == "numberOfFinishingStepovers":
                    param.value.value = 0
                print(f"  -> set to {param.value.value}")
            else:
                print(f"  -> NOT integer type, it's {type(param.value).__name__}")
        else:
            print(f"  {param_name}: NOT FOUND")

    # Verify
    print("\n=== Verify integer params ===")
    for param_name in ["maximumRoughingSteps", "numberOfFinishingStepovers"]:
        param = params.itemByName(param_name)
        if param:
            print(f"  {param_name}: {param.value.value}")

