def run(_context):
    import json
    import adsk.cam

    cam = mb.get_cam()
    for s in cam.setups:
        if s.name == "Setup1":
            for o in s.operations:
                if o.name == "Finish Pin":
                    print(f"Operation: {o.name}")
                    print(f"  hasWarning: {o.hasWarning}")
                    print(f"  hasError: {o.hasError}")
                    # Get the warning message
                    warning = o.warning
                    print(f"  warning: {warning}")
                    error = o.error
                    print(f"  error: {error}")

                    # Check operation state
                    print(f"  operationState: {o.operationState}")

                    # Check if there are any parameter warnings
                    params = o.parameters
                    for i in range(params.count):
                        p = params.item(i)
                        if p.warning:
                            print(f"  param warning: {p.name}: {p.warning}")
                        if p.error:
                            print(f"  param error: {p.name}: {p.error}")

